package com.nanum.investment.domain;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="\"TB_MKT_SNAP\"",uniqueConstraints=@UniqueConstraint(name="UK_TB_MKT_SNAP_01",columnNames={"BASE_DT","MKT_SNAP_CD"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class TbMktSnap { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="MKT_SNAP_ID") private Long marketSnapshotId; @Column(name="BASE_DT",nullable=false) private LocalDate baseDate; @Column(name="MKT_SNAP_CD",nullable=false,length=30) private String marketSnapshotCode; @Column(name="MKT_NM",nullable=false,length=100) private String marketName; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="MAIN_IDX_ID") private TbIdx mainIndex; @Column(name="MAIN_IDX_VAL",precision=20,scale=6) private BigDecimal mainIndexValue; @Column(name="MAIN_IDX_CHG_RT",precision=10,scale=4) private BigDecimal mainIndexChangeRate; @Column(name="FRGN_NET_AMT",precision=20,scale=4) private BigDecimal foreignNetAmount; @Column(name="EXCH_RT",precision=20,scale=6) private BigDecimal exchangeRate; @Column(name="ADV_STK_CNT") private Integer advancingStockCount; @Column(name="DECL_STK_CNT") private Integer decliningStockCount; @Column(name="MKT_BREADTH_RT",precision=10,scale=4) private BigDecimal marketBreadthRate; @Column(name="DATA_SRC_CD",nullable=false,length=30) private String dataSourceCode; @Enumerated(EnumType.STRING) @Builder.Default @Column(name="DATA_STS",nullable=false,length=20) private DataStatus dataStatus=DataStatus.FRESH; @Column(name="DATA_AGE_MIN") private Integer dataAgeMinutes; @Column(name="LAST_OK_DTTM") private OffsetDateTime lastOkDateTime; @Column(name="COLLECT_DTTM",insertable=false) private OffsetDateTime collectedDateTime; }
